  return '<div style="margin-top:28px" id="ops-cleaning-table">' + datalist +
    '<div id="ops-cleaning-shot" style="background:#fff;padding:2px 0 10px">' +
    '<div style="display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:10px;flex-wrap:wrap">' +
    '<div>' +
    '<div style="font-size:11px;font-weight:700;color:#6B7280;letter-spacing:.08em;text-transform:uppercase;margin-bottom:2px">Cleaning schedule</div>' +
    '<div style="font-size:18px;font-weight:800;color:#111827;letter-spacing:-.02em">Καθαρισμοί σήμερα ' +
    '<span id="ops-clean-count" style="font-size:13px;font-weight:600;color:#6B7280">(' + doneCount + '/' + clean.length + ')</span></div>' +
    '</div>' +
    '<div style="display:flex;gap:8px;flex-wrap:wrap">' +
    '<button onclick="opsManageCleaners()" title="Add or remove cleaners" style="font-size:12px;padding:6px 12px;border:1px solid #D1D5DB;border-radius:8px;background:#fff;cursor:pointer;color:#374151;font-weight:600">Καθαρίστριες</button>' +
    '<button onclick="opsCopyCleaningImage()" title="Copy this table as an image — paste into chat" style="font-size:12px;padding:6px 12px;border:1px solid #111827;border-radius:8px;background:#111827;cursor:pointer;color:#fff;font-weight:600">Screenshot</button>' +
    '</div></div>' +
    '<div style="border:1px solid #E5E7EB;border-radius:12px;overflow:hidden">' +
    '<table style="width:100%;border-collapse:collapse;font-size:13px">' +
    '<thead><tr style="background:#F9FAFB">' +
    '<th style="padding:0;width:4px;border:none"></th>' +
    '<th style="padding:9px 6px;border-bottom:1px solid #E5E7EB;text-align:center;width:36px;color:#6B7280;font-size:11px;font-weight:700">✓</th>' +
    '<th style="padding:9px 10px;border-bottom:1px solid #E5E7EB;text-align:left;color:#6B7280;font-size:11px;font-weight:700">Κατάλυμα</th>' +
    '<th style="padding:9px 8px;border-bottom:1px solid #E5E7EB;text-align:left;color:#6B7280;font-size:11px;font-weight:700">Καθαρίστρια</th>' +
    '<th style="padding:9px 8px;border-bottom:1px solid #E5E7EB;text-align:left;color:#6B7280;font-size:11px;font-weight:700">Εργασία</th>' +
    '<th style="padding:9px 8px;border-bottom:1px solid #E5E7EB;text-align:left;color:#6B7280;font-size:11px;font-weight:700">Σχόλια</th>' +
    '</tr></thead><tbody>' + body + '</tbody></table></div>' +
    '</div>' +
    dailyBlocks +
    '</div>';
}

